674	def _normalize_set_value(field_name, value):
675	    """校验 set 操作的值并返回最终入库值；非法时抛 BatchUpdateError。
676	
677	    去除前后空白；仅含空白按清空（None）处理；来源/地区/行业保留内部空白与换行；
678	    重要日期非空时须为 YYYY-MM-DD 真实日历日期。
679	    """
680	    if not isinstance(value, str):
681	        raise BatchUpdateError("%s的设置值不是文本" % FIELD_LABELS[field_name])
682	    text = value.strip()
683	    if not text:
684	        return None
685	    if field_name == "important_date":
686	        ok, reason = check_date(text)
687	        if not ok:
688	            raise BatchUpdateError(reason)
689	    return text
