692	def batch_update_clients(database, payload):
693	    """执行批量修改，返回 {"updated_count": 去重后的客户数}；非法请求抛 BatchUpdateError。
694	
695	    任一问题都整次拒绝，不写入任何客户。
696	    """
697	    if not isinstance(payload, dict):
698	        raise BatchUpdateError("请求体必须是 JSON 对象")
699	
700	    raw_ids = payload.get("ids")
701	    if not isinstance(raw_ids, list):
702	        raise BatchUpdateError("ids 必须是客户编号数组")
703	    if not raw_ids:
704	        raise BatchUpdateError("未选择客户：请先勾选至少一名客户")
705	
706	    ids = []
707	    seen_ids = set()
708	    for raw_id in raw_ids:
709	        if isinstance(raw_id, bool) or not isinstance(raw_id, int) or raw_id <= 0:
710	            raise BatchUpdateError("客户编号必须是正整数：%r 不合法" % (raw_id,))
711	        if raw_id > MAX_CLIENT_ID:
712	            raise BatchUpdateError(
713	                "客户编号超出可接受范围：%d（编号须在 1 到 %d 之间）"
714	                % (raw_id, MAX_CLIENT_ID))
715	        if raw_id not in seen_ids:
716	            seen_ids.add(raw_id)
717	            ids.append(raw_id)
718	
719	    raw_updates = payload.get("updates", {})
720	    if not isinstance(raw_updates, dict):
721	        raise BatchUpdateError("updates 必须是字段修改说明对象")
722	    extra = [key for key in raw_updates if key not in OPTIONAL_FIELDS]
723	    if extra:
724	        raise BatchUpdateError("包含不能修改或不存在的字段：%s" % "、".join(extra))
725	
726	    actions = {}
727	    for field_name in OPTIONAL_FIELDS:
728	        spec = raw_updates.get(field_name, {"op": "keep"})
729	        if not isinstance(spec, dict):
730	            raise BatchUpdateError("%s的修改说明必须是对象" % FIELD_LABELS[field_name])
731	        op = spec.get("op")
732	        if op not in ("keep", "set", "clear"):
733	            raise BatchUpdateError(
734	                "%s的操作必须是 keep、set 或 clear 之一" % FIELD_LABELS[field_name])
735	        if op == "keep":
736	            continue
737	        if op == "clear":
738	            actions[field_name] = None
739	        else:
740	            actions[field_name] = _normalize_set_value(field_name, spec.get("value"))
741	
742	    if not actions:
743	        raise BatchUpdateError("全部字段均保持原值：请至少选择一个字段进行设置或清空")
744	
745	    # 一次选择的客户数可能超过 SQLite 单条语句的参数上限，存在性检查与 UPDATE
746	    # 都按参数上限分块；UPDATE 的多个分块在同一事务内一次提交，整笔修改要么
747	    # 全部生效要么全部不生效，不会因分块变成多次部分修改。
748	    variable_limit = sql_variable_limit(database)
749	
750	    existing = set()
751	    for id_chunk in _chunked(ids, variable_limit):
752	        placeholders = ",".join("?" for _ in id_chunk)
753	        existing.update(
754	            row[0]
755	            for row in database.execute(
756	                "SELECT id FROM clients WHERE id IN (%s)" % placeholders, id_chunk
757	            )
758	        )
759	    missing = [cid for cid in ids if cid not in existing]
760	    if missing:
761	        raise BatchUpdateError("找不到对应客户，编号：%s" % "、".join(str(c) for c in missing))
762	
763	    # 每条 UPDATE 还要为每个修改字段绑定一个赋值参数，编号分块需相应留出位置。
764	    id_chunk_size = max(1, variable_limit - len(actions))
765	    assignments = ", ".join("%s = ?" % field_name for field_name in actions)
766	    values = list(actions.values())
767	    try:
768	        for id_chunk in _chunked(ids, id_chunk_size):
769	            placeholders = ",".join("?" for _ in id_chunk)
770	            database.execute(
771	                "UPDATE clients SET %s WHERE id IN (%s)" % (assignments, placeholders),
772	                values + id_chunk,
773	            )
774	        database.commit()
775	    except sqlite3.DatabaseError:
776	        database.rollback()
777	        raise BatchUpdateError("保存失败：数据库错误，本次修改未生效")
778	
779	    return {"updated_count": len(ids)}
